/* ===== dp1: quy hoạch động, đừng tính lại ===== */
const FIB = "def fib(n):\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)\n";
const fibv = n => n < 2 ? n : fibv(n - 1) + fibv(n - 2);
const fibCalls = (n, t) => { let c = 0; const f = m => { if (m == t) c++; if (m < 2) return; f(m - 1); f(m - 2) }; f(n); return c };
PRB.dp1 = {
  same: () => { const n = fR(4, 8), c = FIB + `print(fib(${n}))`; return aPy(fT(`${fPre(c)}In ra mấy? (fib(0) = 0, fib(1) = 1)`, fibv(n), `Dãy: 0, 1, 1, 2, 3, 5, 8, 13, 21: fib(${n}) = ${fibv(n)}.`), c, [String(fibv(n))]) },
  flip: () => { const n = fR(3, 8); return fT(`Với fib(0) = 0, fib(1) = 1, fib(n) = fib(n - 1) + fib(n - 2), biết fib(?) = ${fibv(n)}. Dấu ? là mấy?`, n, `Dãy 0, 1, 1, 2, 3, 5, 8, 13, 21: ${fibv(n)} đứng ở vị trí ${n}.`) },
  new: () => { const n = fR(4, 7), c = `c = 0\ndef fib(n):\n    global c\n    if n == 2:\n        c += 1\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)\nfib(${n})\nprint(c)`; return aPy(fT(`${fPre(FIB)}Tính fib(${n}) bằng cách thuần này (không ghi nhớ). Hàm fib(2) bị gọi bao nhiêu lần?`, fibCalls(n, 2), `Đếm các lời gọi fib(2) trong cây gọi: ${fibCalls(n, 2)}.`), c, [String(fibCalls(n, 2))]) },
  verdict: KV("Hà nói: 'ghi nhớ kết quả (memo) làm kết quả của fib khác đi so với tính thuần'. Hà nói đúng hay sai?", "Hà nói: 'memo giữ nguyên kết quả, chỉ bỏ việc tính lại những bài con đã tính'. Hà nói đúng hay sai?", "Mỗi bài con chỉ tính một lần rồi tra lại", "Kết quả bị sai khác", "Memo chỉ làm đẹp code", "Sai: kết quả giữ nguyên, chỉ nhanh hơn."),
  read: () => { const n = fR(4, 6); const c = `c = 0\ndef fib(n):\n    global c\n    if n == 1:\n        c += 1\n    if n < 2:\n        return n\n    return fib(n - 1) + fib(n - 2)\nfib(${n})\nprint(c)`; return aPy(aNum(`${fPre(FIB)}Đọc kỹ đề: khi tính fib(${n}), hàm fib(1) (KHÔNG phải fib(2)) bị gọi bao nhiêu lần?`, fibCalls(n, 1), `Đếm riêng fib(1): ${fibCalls(n, 1)} lần. fib(2) bị gọi ${fibCalls(n, 2)} lần, một câu hỏi khác.`, [fibCalls(n, 2), fibCalls(n, 0)]), c, [String(fibCalls(n, 1))]) }
};
