/* ===== dp2: bảng quy hoạch động, leo cầu thang ===== */
const stairs = (n, steps) => { const w = [1]; for (let i = 1; i <= n; i++) { w[i] = 0; for (const s of steps) if (i - s >= 0) w[i] += w[i - s] } return w[n] };
